var checklist = new ArcOnboardingChecklist
{
    Title = "Set up your workspace",
    DoneTitle = "Workspace ready",
    DefaultCompleted = new[] { "profile" },
    Steps = new List<ArcChecklistStep>
    {
        new() { Id = "profile", Title = "Add your profile photo" },
        new()
        {
            Id = "invite",
            Title = "Invite your team",
            Description = "Bring the people who will review and ship with you.",
            ActionLabel = "Invite"
        },
        new() { Id = "connect", Title = "Connect GitHub", ActionLabel = "Connect" }
    }
};

checklist.StepInvoked += (_, step) => OpenStep(step.Id);
